fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Check if the input matrix is empty (shouldn't happen per problem statement)
    if x.is_empty() || x[0].is_empty() {
        return Vec::new();
    }
    
    let rows = x.len();
    let cols = x[0].len();
    
    // Create a result matrix with dimensions swapped
    let mut result = vec![vec![0.0; rows]; cols];
    
    // Fill the transposed matrix
    for i in 0..rows {
        for j in 0..cols {
            result[j][i] = x[i][j];
        }
    }
    
    result
}